package com.naruto.r2;
import com.naruto.port.LauncherActivity;
import android.app.*;
import android.content.*;
import android.net.Uri;
import android.os.Build;
import android.view.*;
import android.widget.*;
import java.io.*;
import java.util.*;
import java.util.concurrent.*;

/** New controls use the launcher's existing cards, buttons and animated switches. */
public final class LauncherUi {
    private static final int EXPORT=8201;
    private static final ExecutorService worker=Executors.newSingleThreadExecutor();
    public static void install(LauncherActivity a){
        LinearLayout root=null;
        if(!a.v.isEmpty()){
            View v=(View)a.v.get(0);
            while(v.getParent() instanceof View){View parent=(View)v.getParent();if((parent instanceof ScrollView||parent.getClass().getName().equals("a.f"))&&v instanceof LinearLayout){root=(LinearLayout)v;break;}v=parent;}
        }
        if(root==null)throw new IllegalStateException("Stock settings container was not found.");
        add(a,root,a.w("More options",buttons(a,new String[]{"Display","Saves","Tools"},new Runnable[]{()->display(a),()->saves(a),()->tools(a)})));

    }
    private static void display(LauncherActivity a){LinearLayout body=dialogBody(a);
        body.addView(ModernUi.text(a,"Graphics changes apply the next time the game starts.",12,ModernUi.MUTED));
        body.addView(ModernUi.text(a,"Frame generation can use a different upscaling path. Send log reports the path observed by the renderer.",12,ModernUi.MUTED));
        body.addView(dialogToggle(a,"Opening video","Show the launcher video","r2_video",true));
        body.addView(ModernUi.action(a,"Screen mode",GameMenu.screenName(GameHooks.prefs(a).getInt("r2_screen",GameHooks.prefs(a).getInt("menu_screen_v3",0))),()->screen(a)));
        body.addView(ModernUi.action(a,"Brightness",null,()->gamma(a)));
        body.addView(ModernUi.action(a,"FPS / statistics size",null,()->StatsOverlay.sizeDialog(a,null)));
        body.addView(ModernUi.action(a,"Shadows",null,()->choice(a,"Shadow quality","r2_shadow",new String[]{"Auto (original)","360 · lower","720 · original cap","1080 · higher"},new int[]{0,360,720,1080},0,null)));
        new ModernUi.Builder(a).setTitle("Display").setView(ModernUi.scroll(a,body)).setPositiveButton("Done",null).show();}
    private static void saves(LauncherActivity a){new ModernUi.Builder(a).setTitle("Save files").setItems(new String[]{"Export current save","Manage backups"},(d,w)->{if(w==0)export(a,null);else backups(a);}).show();}
    private static void tools(LauncherActivity a){new ModernUi.Builder(a).setTitle("Tools").setItems(new String[]{"GPU memory budget","Streaming cache","Driver information"},(d,w)->{if(w==0)choice(a,"GPU memory budget","r2_budget",new String[]{"Auto (recommended)","768 MB","1024 MB","1400 MB","2048 MB"},new int[]{0,768,1024,1400,2048},0,null);else if(w==1)choice(a,"Streaming cache","r2_cache",new String[]{"Auto (recommended)","64 MB","128 MB","256 MB"},new int[]{0,64,128,256},0,null);else driver(a);}).show();}
    private static void add(LauncherActivity a,LinearLayout root,View card){LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.bottomMargin=a.d(6);root.addView(card,lp);}
    private static LinearLayout buttons(LauncherActivity a,String[] titles,Runnable[] tasks){LinearLayout row=new LinearLayout(a);for(int i=0;i<titles.length;i++){final Runnable task=tasks[i];TextView b=a.r2Button(titles[i],0,0xfff5e6bd);b.setTextSize(11);b.setOnClickListener(v->{LauncherActivity.k(v);task.run();});LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,a.d(36),1);lp.setMargins(a.d(2),0,a.d(2),0);row.addView(b,lp);}return row;}
    private static void choice(LauncherActivity a,String title,String key,String[] names,int[] values,int initial,Runnable after){int current=GameHooks.prefs(a).getInt(key,initial),selected=0;for(int i=0;i<values.length;i++)if(values[i]==current)selected=i;new ModernUi.Builder(a).setTitle(title).setSingleChoiceItems(names,selected,(dialog,index)->{GameHooks.prefs(a).edit().putInt(key,values[index]).apply();if(after!=null)after.run();dialog.dismiss();}).setNegativeButton("Cancel",null).show();}
    private interface FloatValue{void set(float value);}
    private static View slider(LauncherActivity a,String label,float initial,float min,float max,FloatValue changed){LinearLayout row=new LinearLayout(a);row.setOrientation(1);TextView text=new TextView(a);text.setTextColor(0xfff5e6bd);text.setText(String.format(Locale.ROOT,"%s: %.2f",label,initial));row.addView(text);SeekBar bar=new SeekBar(a);bar.setMax(1000);bar.setProgress(Math.round((initial-min)/(max-min)*1000));bar.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onStartTrackingTouch(SeekBar b){}public void onStopTrackingTouch(SeekBar b){}public void onProgressChanged(SeekBar b,int n,boolean user){float value=min+(max-min)*n/1000f;text.setText(String.format(Locale.ROOT,"%s: %.2f",label,value));if(user)changed.set(value);}});row.addView(bar);return row;}
    private static LinearLayout dialogBody(LauncherActivity a){LinearLayout body=new LinearLayout(a);body.setOrientation(1);body.setPadding(a.d(18),a.d(8),a.d(18),a.d(8));return body;}
    private static void gamma(LauncherActivity a){LinearLayout body=dialogBody(a);body.addView(slider(a,"Brightness / gamma",GameHooks.prefs(a).getFloat("r2_gamma",1),.5f,2,v->GameHooks.prefs(a).edit().putFloat("r2_gamma",v).apply()));new ModernUi.Builder(a).setTitle("Brightness").setView(ModernUi.scroll(a,body)).setNeutralButton("Reset",(d,w)->GameHooks.prefs(a).edit().remove("r2_gamma").apply()).setPositiveButton("Done",null).show();}
    private static void screen(LauncherActivity a){choice(a,"Screen mode","r2_screen",new String[]{"Fit · full image, correct proportions","Stretch · original fullscreen option","Crop · fill screen, correct proportions"},new int[]{0,1,2},GameHooks.prefs(a).getInt("menu_screen_v3",0),()->{int mode=GameHooks.prefs(a).getInt("r2_screen",0);GameHooks.prefs(a).edit().putInt("menu_screen_v3",mode==1?1:0).putBoolean("stretch",mode==1).apply();if(mode==2){LinearLayout body=dialogBody(a);TextView preview=new TextView(a);preview.setText("Cropping fills the display by cutting off part of the top/bottom or sides. It does not stretch the picture.");preview.setTextColor(0xfff5e6bd);body.addView(preview);body.addView(slider(a,"Crop amount",GameHooks.prefs(a).getInt("r2_crop",100)/100f,0,1,v->GameHooks.prefs(a).edit().putInt("r2_crop",Math.round(v*100)).apply()));new ModernUi.Builder(a).setTitle("Fullscreen crop").setView(ModernUi.scroll(a,body)).setNeutralButton("Reset",(d,w)->GameHooks.prefs(a).edit().remove("r2_crop").apply()).setPositiveButton("Done",null).show();}});}
    private static View dialogToggle(LauncherActivity a,String title,String detail,String key,boolean initial){return ModernUi.toggle(a,title,detail,GameHooks.prefs(a).getBoolean(key,initial),(v,on)->GameHooks.prefs(a).edit().putBoolean(key,on).apply());}
    private static void driver(LauncherActivity a){a.q();new ModernUi.Builder(a).setTitle("GPU driver").setMessage(DriverSupport.information(a)).setNeutralButton("Use system driver",(d,w)->a.p("")).setPositiveButton("Done",null).show();}
    private static void export(LauncherActivity a,File backup){GameHooks.prefs(a).edit().putString("r2_pending_export",backup==null?"save":"backup").putString("r2_pending_backup",backup==null?"":backup.getAbsolutePath()).apply();Intent pick=new Intent(Intent.ACTION_CREATE_DOCUMENT);pick.addCategory(Intent.CATEGORY_OPENABLE);pick.setType("application/zip");pick.putExtra(Intent.EXTRA_TITLE,"STORMR-save-"+System.currentTimeMillis()+".zip");a.startActivityForResult(pick,EXPORT);}
    private interface Work{String run()throws Exception;}
    private static void job(LauncherActivity a,String title,Work task){AlertDialog progress=new ModernUi.Builder(a).setTitle(title).setMessage("Please wait…").setCancelable(false).show();worker.execute(()->{String message;try{message=task.run();}catch(Exception e){message="Could not complete the operation: "+e.getMessage();}String result=message;a.runOnUiThread(()->{if(!a.isFinishing()&&!a.isDestroyed()){progress.dismiss();if(result!=null)new ModernUi.Builder(a).setMessage(result).setPositiveButton("OK",null).show();}});});}
    public static boolean activityResult(LauncherActivity a,int request,int result,Intent data){if(request!=EXPORT)return false;if(result!=Activity.RESULT_OK||data==null||data.getData()==null){GameHooks.prefs(a).edit().remove("r2_pending_export").remove("r2_pending_backup").apply();return true;}Uri uri=data.getData();String kind=GameHooks.prefs(a).getString("r2_pending_export","");String backupPath=GameHooks.prefs(a).getString("r2_pending_backup","");GameHooks.prefs(a).edit().remove("r2_pending_export").remove("r2_pending_backup").apply();if(!kind.equals("save")&&!kind.equals("backup")){new ModernUi.Builder(a).setMessage("The export request expired. Please try again.").setPositiveButton("OK",null).show();return true;}File backup=kind.equals("backup")?new File(backupPath):null;job(a,"Export",()->{OutputStream stream=a.getContentResolver().openOutputStream(uri,"wt");if(stream==null)throw new IOException("The selected destination could not be opened.");try(OutputStream out=stream){try(SaveFiles files=new SaveFiles(a.getExternalFilesDir(null),a.getFilesDir())){if(backup==null)files.exportCurrent(out);else files.exportBackup(backup,out);}}a.runOnUiThread(()->{if(a.isFinishing()||a.isDestroyed())return;new ModernUi.Builder(a).setTitle("Export saved").setMessage("Share the exported file?").setNegativeButton("Not now",null).setPositiveButton("Share",(d,w)->{Intent share=new Intent(Intent.ACTION_SEND).setType("application/zip").putExtra(Intent.EXTRA_STREAM,uri).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);share.setClipData(ClipData.newRawUri("STORM R export",uri));a.startActivity(Intent.createChooser(share,"Share export"));}).show();});return null;});return true;}
    private static void backups(LauncherActivity a){try(SaveFiles files=new SaveFiles(a.getExternalFilesDir(null),a.getFilesDir())){File[] entries=files.list();String[] names=new String[entries.length];for(int i=0;i<entries.length;i++)names[i]=entries[i].getName();new ModernUi.Builder(a).setTitle("Save backups").setItems(names,(d,w)->backupActions(a,entries[w])).setNeutralButton("Create backup",(d,w)->job(a,"Save backup",()->{try(SaveFiles saves=new SaveFiles(a.getExternalFilesDir(null),a.getFilesDir())){return "Backup created: "+saves.backupCurrent().getName();}})).setNegativeButton("Done",null).show();}catch(IOException e){new ModernUi.Builder(a).setMessage(e.getMessage()).setPositiveButton("OK",null).show();}}
    private static void backupActions(LauncherActivity a,File backup){new ModernUi.Builder(a).setTitle(backup.getName()).setItems(new String[]{"Export backup","Restore backup","Delete backup"},(d,w)->{if(w==0){export(a,backup);return;}new ModernUi.Builder(a).setTitle(w==1?"Restore this backup?":"Delete this backup?").setMessage(w==1?"The current save will be backed up first. Restoring is blocked while the 100% save is active.":"Only this backup will be removed. The active save and bundled 100% save are kept.").setNegativeButton("Cancel",null).setPositiveButton(w==1?"Restore":"Delete",(dd,ww)->job(a,"Save backups",()->{try(SaveFiles files=new SaveFiles(a.getExternalFilesDir(null),a.getFilesDir())){if(w==1)files.restore(backup);else files.deleteBackup(backup);return w==1?"Backup restored.":"Backup deleted.";}})).show();}).show();}
}
